-- holidaydescriptions: 0 inserts, 28 updates, 0 deletes

-- Changed values
UPDATE `holidaydescriptions` SET `description_kokr` = '이번에는 다크문 축제가 여기, 목가적인 풍경이 펼쳐진 엘윈 숲에서 열립니다. 실라스 다크문과 그 유랑단을 만나 보세요. 속마음을 점쳐보기도 하고 아제로스 구석구석에서 모인 신기한 여러 가지를 물건을 즐기실 수도 있답니다... 이게 전부가 아니니 직접 가보세요!', `description_frfr` = 'La foire de Sombrelune est installée dans la sublime forêt d\'Elwynn.

Rendez visite à Silas Sombrelune et sa troupe, jouez à des jeux qui mettront à l\'épreuve votre esprit et vos nerfs, et découvrez des visions exotiques venues des quatre coins d\'Azeroth… et au-delà !', `description_dede` = 'Der Dunkelmond-Jahrmarkt ist hier, diesmal im Wald von Elwynn.

Trefft Silas Dunkelmond und seine Truppe, spielt Spiele, die Kopf und Nerven auf die Probe stellen und bewundert exotische Anblicke aus allen Himmelsrichtungen Azeroths... und darüber hinaus!', `description_zhcn` = '这一次，暗月马戏团来到了风景如画的艾尔文森林。

去拜访希拉斯·暗月和他的马戏团，玩一玩考验头脑和胆量的游戏，看一看来自艾泽拉斯各地的奇特珍品……还有更多的乐趣在等着你！', `description_zhtw` = '暗月馬戲團來了，就在田園般的艾爾文森林中。

快來看看希拉斯·暗月和他的戲團，參與一些考驗智慧與膽量的遊戲，目睹來自艾澤拉斯各地的驚奇景象…以及更多新奇的事物在此等著你!', `description_eses` = 'La Feria de la Luna Negra ya está aquí, en el idílico Bosque de Elwynn.

Conoce a Silas Lunanegra y a su compañía, diviértete con juegos que ponen a prueba tu mente y tu nervio, y contempla vistas exóticas de todos los rincones de Azeroth... ¡y más allá!', `description_esmx` = 'La Feria de la Luna Negra ya está aquí, en el idílico Bosque de Elwynn.

Conoce a Silas Lunanegra y a su compañía, diviértete con juegos que ponen a prueba tu mente y tu nervio, y contempla vistas exóticas de todos los rincones de Azeroth... ¡y más allá!', `description_ruru` = 'В тихий Элвиннский лес приехала Ярмарка Новолуния!

Познакомься с Сайласом Новолунием и его труппой, испытай свою смелость и ловкость и полюбуйся роскошными видами со всего Азерота и за его пределами!' WHERE `id` = 1;
UPDATE `holidaydescriptions` SET `description_kokr` = '아제로스가 새해를 맞이했습니다! 각 대도시에서는 밤새도록 흥겨운 불꽃놀이가 펼쳐집니다.', `description_frfr` = 'Azeroth est en fête ! Vous pouvez admirer un feu d’artifice toutes les heures dans les capitales, et ce pendant toute la nuit !', `description_dede` = 'Azeroth feiert! In der Hauptstadt jedes Volkes gibt es zu jeder Stunde ein Feuerwerk - und das die ganze Nacht lang!', `description_zhcn` = '艾泽拉斯的大庆典！每个种族的主城中都会燃放美丽的烟花，每小时一次，整夜不停！', `description_zhtw` = '艾澤拉斯慶典!所有種族的主城每小時都會舉辦煙火表演秀，徹夜狂歡!', `description_eses` = '¡Azeroth está de celebraciones! ¡Cada capital de raza tiene fuegos artificiales cada hora toda la noche!', `description_esmx` = '¡Azeroth está de celebraciones! ¡Cada capital de raza tiene fuegos artificiales cada hora toda la noche!', `description_ruru` = 'Азерот празднует Новый Год!' WHERE `id` = 2;
UPDATE `holidaydescriptions` SET `description_kokr` = '가시덤불 골짜기 해안을 따라 펼쳐지는 낚시대회입니다. 맛둥어를 가능한 한 많이 낚아 올리세요! 맛둥어 40마리를 먼저 낚고 우승 상품을 차지할 낚시의 대가는 과연 누구일까요?', `description_frfr` = 'Un tournoi de pêche qui se déroule le long des côtes de la vallée de Strangleronce. Pêchez autant de courbines que possible !

Serez-vous le maître pêcheur, qui, le premier, attrapera quarante poissons et gagnera le grand prix ?', `description_dede` = 'Ein Angelturnier, das an der Küste des Schlingendorntals abgehalten wird. Fangt so viele Leckerfische, wie Ihr nur könnt!

Werdet Ihr der Meisterangler, der am schnellsten vierzig Fische fängt und den großen Preis gewinnt?', `description_zhcn` = '在荆棘谷沿岸举行的钓鱼大赛。钓到尽可能多的可口鱼！

你会不会成为第一个钓到40条鱼、赢得大奖的钓鱼大师呢？', `description_zhtw` = '一場在荊棘谷的海岸舉辦的釣魚大賽。看你能釣起多少美味的魚!

你會是最先釣起四十隻魚的釣魚大師，並且贏得大獎嗎?', `description_eses` = 'Torneo de pesca, que se celebra por las costas de Vega de Tuercespina. ¡Captura todo el pezrico que puedas! 

¿Serás tú el primer gran pescador que capture cuarenta peces y se lleve el gran premio?', `description_esmx` = 'Torneo de pesca, que se celebra por las costas de Vega de Tuercespina. ¡Captura todo el pezrico que puedas! 

¿Serás tú el primer gran pescador que capture cuarenta peces y se lleve el gran premio?', `description_ruru` = 'Турнир рыболовов собирает лучших мастеров в Тернистой долине. Поймай как можно больше вкуснорыб – и стань чемпионом!

Сможешь ли ты завоевать главный приз, быстрее всех выловив сорок блестящих рыбин?' WHERE `id` = 4;
UPDATE `holidaydescriptions` SET `description_kokr` = '처음에는 드워프만이 즐기던 행사였으나 이제는 아제로스 모든 종족이 함께 즐기는 가을 축제입니다! 아이언포지 외곽에 있는 얼라이언스 야영지나 오그리마 외곽에 있는 호드 야영지를 찾아가 보세요. 신나는 일들이 기다리고 있답니다!', `description_frfr` = 'D\'abord célébrée par les nains, la fête des Brasseurs attire aujourd\'hui toutes les races d\'Azeroth !

Rendez-vous dans le camp de l\'Alliance, à l\'extérieur de Forgefer, ou dans le camp de la Horde, à l\'extérieur d\'Orgrimmar, et joignez-vous à la fête !', `description_dede` = 'Es wurde von den Zwergen ins Leben gerufen und begeistert nun alle Völker Azeroths!

Besucht das Lager der Allianz vor den Toren von Eisenschmiede oder das Lager der Horde vor den Toren Orgrimmars und feiert mit!', `description_zhcn` = '美酒节最初是矮人的节日，但现在已经成为了艾泽拉斯所有种族都喜欢的节日！

前往铁炉堡外面的联盟营地，或是奥格瑞玛外面的部落营地参加狂欢吧！', `description_zhtw` = '最早由矮人開始慶祝，如今啤酒節歡迎艾澤拉斯的所有種族!

去拜訪鐵爐堡外的聯盟營地或奧格瑪外的部落營地，一起同樂吧!', `description_eses` = 'Los enanos fueron los primeros en celebrar la Fiesta de la cerveza, ¡que ahora atrae a todas las razas de Azeroth!

Visita el campamento de la Alianza a las afueras de Forjaz o el campamento de la Horda a las afueras de Orgrimmar, ¡y únete a la fiesta!', `description_esmx` = 'Los enanos fueron los primeros en celebrar la Fiesta de la cerveza, ¡que ahora atrae a todas las razas de Azeroth!

Visita el campamento de la Alianza a las afueras de Forjaz o el campamento de la Horda a las afueras de Orgrimmar, ¡y únete a la fiesta!', `description_ruru` = 'Первыми Хмельной фестиваль стали проводить дворфы, но он завоевал популярность и у всех остальных жителей Азерота.

Посети лагерь Альянса возле Стальгорна или загляни в шатер Орды рядом с Оргриммаром – главное, не пропусти веселье!' WHERE `id` = 8;
UPDATE `holidaydescriptions` SET `description_kokr` = '아제로스의 주요 도시에 특별한 분위기가 감돕니다. 경비병이나 도시 주민들은 좋아하는 이와 선물을 주고받으며 이날을 보냅니다.', `description_frfr` = 'Il y a quelque chose dans l\'air dans les capitales d\'Azeroth. Gardes et habitants passent leurs journées à donner des cadeaux à d\'autres citoyens amoureux et à en recevoir.', `description_dede` = 'In den großen Städten Azeroths liegt etwas in der Luft. Viele Wachen und Einwohner verbringen Tage damit, Geschenke an andere verliebte Bürger zu verteilen oder solche zu erhalten.', `description_zhcn` = '艾泽拉斯的各大主城中，弥漫着浪漫温馨的气息。卫兵与市民们正在忙碌地送出和收到各种代表倾慕之情的礼物。', `description_zhtw` = '艾澤拉斯的主城中瀰漫著不同的氣氛。許多守衛與平民會在這段期間內與其愛慕的對象互贈禮物。', `description_eses` = 'Algo flota en el aire de las grandes ciudades de Azeroth. Numerosos guardias y ciudadanos pasan unos días intercambiando regalos con otros amorosos vecinos.', `description_esmx` = 'Algo flota en el aire de las grandes ciudades de Azeroth. Numerosos guardias y ciudadanos pasan unos días intercambiando regalos con otros amorosos vecinos.', `description_ruru` = 'Любовная лихорадка охватила все большие города Азерота. Забыты ссоры и распри; горожане и стражи обмениваются поцелуями и подарками!' WHERE `id` = 9;
UPDATE `holidaydescriptions` SET `description_kokr` = '일 년 중, 가장 뜨거운 계절을 기념하여 모두가 떠들고 즐기는 시간입니다.', `description_frfr` = 'Un moment de joie et de fête, dédié à la plus chaude saison de l\'année.', `description_dede` = 'Eine Zeit der Fröhlichkeit und des Feierns, die der heißesten Jahreszeit gewidmet ist.', `description_zhcn` = '一个欢笑与庆祝的时刻，以纪念一年中最热的季节。', `description_zhtw` = '歡樂與慶祝的時間，獻給一年之中最炎熱的季節。', `description_eses` = 'Una época de alegría y celebración dedicada a la estación más calurosa del año.', `description_esmx` = 'Una época de alegría y celebración dedicada a la estación más calurosa del año.', `description_ruru` = 'Давайте весело отметим наступление самого жаркого времени года!' WHERE `id` = 10;
UPDATE `holidaydescriptions` SET `description_kokr` = '해가 진 후에는, 한여름의 열기를 축하하는 뜻으로 매시간 화려한 불꽃놀이가 펼쳐집니다. 불꽃놀이를 보고 싶으시면 주요 도시나 무법항을 찾아 주세요.', `description_frfr` = 'Lorsque le soleil se couche, la fin du solstice est célébrée toutes les heures par des feux d\'artifice époustouflants.

Pour voir le spectacle, rendez-vous dans n\'importe quelle capitale ou à Baie-du-Butin.', `description_dede` = 'Nach Sonnenuntergang wird das Ende der Sonnenwende mit einem stündlichen Feuerwerk gefeiert.

Begebt Euch in eine der Hauptstädte oder nach Beutebucht, um das Spektakel zu sehen.', `description_zhcn` = '在日落之后，伴随着每小时一次的焰火舞会，仲夏火焰节将缓缓落下帷幕。

想要观看表演的话，可以前去各大主城或者藏宝海湾。', `description_zhtw` = '在仲夏的最後一天，日落之後大肆慶祝，接連好幾個小時的煙火大會。

想要參觀表演的話，請前往各大主城或藏寶海灣。', `description_eses` = 'Cuando el sol se pone, se celebra el final del solsticio de verano con un gran espectáculo de fuegos artificiales cada hora.

Para verlo, visita cualquier capital o Bahía del Botín.', `description_esmx` = 'Cuando el sol se pone, se celebra el final del solsticio de verano con un gran espectáculo de fuegos artificiales cada hora.

Para verlo, visita cualquier capital o Bahía del Botín.', `description_ruru` = 'Праздник Огненного солнцеворота отмечается после захода солнца.

Полюбуйся роскошным фейерверком в одной из столиц Азерота или в Пиратской Бухте.' WHERE `id` = 11;
UPDATE `holidaydescriptions` SET `description_kokr` = '영웅이란 어떤 삶을 사는지, 고아 어린이들에게 직접 보여주세요! 스톰윈드의 나이팅게일 보육원 원장님이나 오그리마의 배틀웨일 보육원 원장님, 샤트라스의 머시 보육원 원장님, 달라란의 아리아 보육원 원장님을 만나보시고 어린이들의 소망을 이뤄주세요.', `description_frfr` = 'Montrez à un orphelin à quoi ressemble la vie d\'un héros ! Rendez visite à la directrice de l\'orphelinat Rossignol à Hurlevent, à la directrice de l\'orphelinat Plainteguerre à Orgrimmar, à Miss Hérikorde à Shattrath, ou à la directrice de l\'orphelinat Aria à Dalaran, et réalisez les rêves d\'un enfant !', `description_dede` = 'Zeigt einem Waisenkind, wie das Leben eines Helden aussieht! Besucht Waisenmatrone Nachtigall in Sturmwind, Waisenmatrone Schlachterbe in Orgrimmar, Waisenmatrone Gnädig in Shattrath oder Waisenmatrone Aria in Dalaran und lasst den Traum eines Kindes in Erfüllung gehen.', `description_zhcn` = '让孤儿看看英雄的生活是怎样的！拜访暴风城的孤儿监护员奈丁加尔，奥格瑞玛的孤儿监护员巴特维尔，或是沙塔斯城的孤儿院长莫希。让孩子们梦想成真吧！', `description_zhtw` = '讓一個孤兒瞧瞧英雄的日常生活!去拜訪暴風城的孤兒監護員南丁格爾或奧格瑪的孤兒監護員巴特維爾，並且讓一個孩子美夢成真。', `description_eses` = '¡Enséñale a un niño huérfano cómo es la vida de un héroe! Ve a ver a la supervisora de huérfanos Ruiseñor en Ventormenta, a la supervisora de huérfanos Llantobatalla en Orgrimmar, a la supervisora de huérfanos Piedad en Shattrath o a la supervisora de huérfanos Aria en Dalaran y haz realidad el sueño de un niño.', `description_esmx` = '¡Enséñale a un niño huérfano cómo es la vida de un héroe! Ve a ver a la supervisora de huérfanos Ruiseñor en Ventormenta, a la supervisora de huérfanos Llantobatalla en Orgrimmar, a la supervisora de huérfanos Piedad en Shattrath o a la supervisora de huérfanos Aria en Dalaran y haz realidad el sueño de un niño.', `description_ruru` = 'Покажи сиротке жизнь настоящего искателя приключений! Загляни к попечительнице сирот Найтингейл в Штормграде, к попечительнице сирот Батлвейл в Оргриммаре или к попечительнице сирот Миле в Шаттрате и исполни самые сокровенные мечты маленьких детишек!' WHERE `id` = 12;
UPDATE `holidaydescriptions` SET `description_kokr` = '겨울 할아버지가 굴뚝나무 목장조합의 승인을 받아 오그리마와 아이언포지를 방문합니다. 아제로스 어디나 즐거움이 가득 넘쳐납니다!', `description_frfr` = 'Le Grand-père Hiver se rend dans les villes de Forgefer et d\'Orgrimmar, avec l\'aimable autorisation des Gourmandises Fumebois. Et dans tout Azeroth, c\'est la saison de la bonne humeur !', `description_dede` = 'Großvater Winter besucht mit freundlicher Unterstützung von Kokelwälder die Städte Eisenschmiede und Orgrimmar und in ganz Azeroth bricht eine fröhliche Jahreszeit an!', `description_zhcn` = '冬天爷爷正在带着烟林牧场的礼物访问铁炉堡和奥格瑞玛。整个艾泽拉斯到处充满着节日的喜庆气氛！', `description_zhtw` = '冬天爺爺來拜訪鐵爐堡與奧格瑪了，還有燻木農場的禮物。在艾澤拉斯各地，這都是個充滿歡樂的季節!', `description_eses` = 'El Gran Padre Invierno está visitando las ciudades de Forjaz y Orgrimmar, por cortesía de los Pastos de Bosquehumeante. Y por todo Azeroth ¡es la temporada de la alegría!', `description_esmx` = 'El Gran Padre Invierno está visitando las ciudades de Forjaz y Orgrimmar, por cortesía de los Pastos de Bosquehumeante. Y por todo Azeroth ¡es la temporada de la alegría!', `description_ruru` = 'Скоро в Стальгорн и Оргриммар придет Дедушка Зима. Он везет нам подарки с Пастбищ Дымного Леса! Веселись, Азерот, наступает Новый Год!' WHERE `id` = 13;
UPDATE `holidaydescriptions` SET `description_kokr` = '귀족의 정원에서 향연이 시작되었습니다. 종족마다 젊은 영웅들이 처음으로 능력을 시험받는 시험장에 교묘하게 숨겨진 보물 알이 있습니다. 몇 개나 찾을 수 있을까요?', `description_frfr` = 'La fête du Jardin des nobles est arrivée. Les terres où chaque jeune héros teste ses forces pour la première fois cachent toutes des œufs remplis de trésors. Combien arriverez-vous à en trouver ?', `description_dede` = 'Das Nobelgartenfest ist da. Die Zeit für jedes Volk, sich zu beweisen, wenn junge Helden zum ersten Mal ihre Stärke testen und nach clever versteckten Schatzeiern suchen. Wie viele könnt Ihr finden?', `description_zhcn` = '复活节到了。许多彩蛋巧妙地隐藏在每个种族的新手区域——年轻的英雄们初次检验自己力量的地方，你能找到多少呢？', `description_zhtw` = '貴族花園的慶典已經來嘍。這是屬於所有種族的場合，年輕的英雄們在此初試啼聲，尋找被巧妙收藏的藏寶蛋。你找到了幾個呢?', `description_eses` = 'La celebración del Jardín Noble ya está aquí. Los terrenos de pruebas de cada raza, el lugar donde los jóvenes héroes demuestran su fuerza por primera vez, esconden con ingenio pequeños huevos ocultos. ¿Cuántos eres capaz de encontrar?', `description_esmx` = 'La celebración del Jardín Noble ya está aquí. Los terrenos de pruebas de cada raza, el lugar donde los jóvenes héroes demuestran su fuerza por primera vez, esconden con ingenio pequeños huevos ocultos. ¿Cuántos eres capaz de encontrar?', `description_ruru` = 'По всему Азероту начинается празднование Сада чудес! Юные герои, испытайте свои силы в это волшебное время, когда в каждом укромном местечке можно отыскать яйцо с подарком. Сколько удастся найти вам?' WHERE `id` = 14;
UPDATE `holidaydescriptions` SET `description_kokr` = '할로윈 축제는 포세이큰이 스컬지로부터 해방된 것을 축하하는 행사입니다. 누구든 요청하기만 하면 아제로스에 있는 여관주인들에게서 선물을 받을 수 있습니다. 그 선물이 진짜 선물일지 무언가 다른 것일지는 열어봐야 알겠지만요.', `description_frfr` = 'La Sanssaint célèbre la séparation entre les Réprouvés et le Fléau.

La fête et l\'espièglerie règnent tandis que les aubergistes d\'Azeroth distribuent bonbons et blagues à qui le leur demande.', `description_dede` = 'In den Schlotternächten wird die Abspaltung der Verlassenen von der Geißel gefeiert.

Spaß und Unsinn regieren, wenn die Gastwirte Azeroths Süßes und Saures an alle verteilen, die danach fragen.', `description_zhcn` = '万圣节是被遗忘者庆祝自己摆脱天灾军团控制的节日。

艾泽拉斯的旅店老板们会向所有上门问候的人送出糖果或恶作剧，到处都是欢乐的笑声。', `description_zhtw` = '萬鬼節是為了慶祝被遺忘者掙脫天譴軍團的束縛。

歡笑與惡作劇在各地上演，艾澤拉斯各地的旅店主人提供給每個人小糖果與惡作劇道具。', `description_eses` = 'Halloween celebra la separación de los Renegados de la Plaga.

La diversión y las travesuras reinan por doquier, mientras los taberneros de Azeroth hacen truco o trato a cualquiera que se lo pida.', `description_esmx` = 'Halloween celebra la separación de los Renegados de la Plaga.

La diversión y las travesuras reinan por doquier, mientras los taberneros de Azeroth hacen truco o trato a cualquiera que se lo pida.', `description_ruru` = 'На Тыквовин мы празднуем освобождение Отрекшихся от Плети.

Во всех тавернах Азерота тебя ждут шутки, смех и сладости!' WHERE `id` = 15;
UPDATE `holidaydescriptions` SET `description_kokr` = '추수절은 친구와 동지를 위해 목숨을 바친 이들을 기념하는 시간입니다. 오그리마와 아이언포지 외곽에는 세상을 떠난 영웅을 기리며 잔치가 벌어집니다.', `description_frfr` = 'La fête des Moissons permet de rendre hommage à ceux qui ont sacrifié leur vie pour aider leurs amis et leurs alliés. Des festins sont organisés à Orgrimmar et Forgefer en l\'honneur de ces héros disparus.', `description_dede` = 'Das Erntedankfest ist die Zeit, jenen zu gedenken, die ihr Leben opferten, um Freunden und Familie zu helfen. Feste werden vor den Toren von Orgrimmar und Eisenschmiede abgehalten, um die gefallenen Helden zu ehren.', `description_zhcn` = '收获节的意义，在于纪念那些为帮助朋友和伙伴而牺牲的英雄们。奥格瑞玛和铁炉堡外都在举行盛宴，向那些英雄表示敬意。', `description_zhtw` = '收穫節是紀念那些為了朋友與同伴犧牲生命的勇士。慶典在奧格瑪與鐵爐堡的郊外舉行，以紀念那些死去的英雄。', `description_eses` = 'El Festival de la Cosecha es una ocasión para rendir un homenaje a aquellos que han sacrificado su vida para ayudar a sus amigos y aliados. A las afueras de Orgrimmar y Forjaz se dan banquetes en honor a estos héroes caídos.', `description_esmx` = 'El Festival de la Cosecha es una ocasión para rendir un homenaje a aquellos que han sacrificado su vida para ayudar a sus amigos y aliados. A las afueras de Orgrimmar y Forjaz se dan banquetes en honor a estos héroes caídos.', `description_ruru` = 'Неделя урожая – это время вспомнить о тех, кто погиб на полях сражений, защищая друзей и союзников. Мы накрываем столы возле Стальгорна и Оргриммара, чтобы почтить память павших героев.' WHERE `id` = 16;
UPDATE `holidaydescriptions` SET `description_kokr` = '매년 달의 숲 드루이드들은 고대 악을 무찌른 승리를 기념하는 축제를 엽니다. 달의 축제 기간 동안 아제로스의 시민들은 선조들의 명예와 지혜를 기리고, 즐거운 축제를 함께 즐깁니다. 물론 불꽃놀이도 마음껏 즐길 수 있습니다!', `description_frfr` = 'Chaque année, les druides de Reflet-de-lune commémorent la victoire de leur cité sur un mal ancien. Pendant la fête lunaire, les citoyens d’Azeroth ont l’occasion de rendre hommage à leurs anciens en écoutant leurs avis, en participant à de splendides festins et bien entendu… en tirant des feux d’artifice !', `description_dede` = 'Jedes Jahr veranstalten die Druiden der Mondlichtung ein Fest zu Ehren des großen Sieges ihrer Stadt über ein uraltes Unheil. Während des Mondfestes erhalten die Bewohner Azeroths die Gelegenheit, ihre Ältesten zu Ehren, indem sie ihre Weisheit feiern, Festmähler miteinander teilen und natürlich... Feuerwerkskörper zünden!', `description_zhcn` = '月光林地的德鲁伊每年都会举行一次庆典，以庆祝他们对一股远古的邪恶力量所取得的胜利。在春节期间，艾泽拉斯的人民可以祭拜睿智的祖先，共享美味的盛宴，还有……绚丽的烟花！', `description_zhtw` = '每年月光林地的德魯伊們都會舉辦一場歡慶他們擊敗一個古老魔物的祭典。在新年節慶期間內，艾澤拉斯的居民們可以趁此佳節來榮耀他們的長者，藉由歌頌他們的智慧，舉辦盛宴，當然還有…數不盡的煙火!', `description_eses` = 'Cada año los druidas del Claro de la Luna celebran el gran triunfo de su ciudad sobre un antiguo mal. Durante el Festival Lunar los ciudadanos de Azeroth tienen la oportunidad de rendir honor a sus ancestros celebrando su sabiduría con magníficos festines y, por supuesto, ¡lanzando fuegos de artificio!|n', `description_esmx` = 'Cada año los druidas del Claro de la Luna celebran el gran triunfo de su ciudad sobre un antiguo mal. Durante el Festival Lunar los ciudadanos de Azeroth tienen la oportunidad de rendir honor a sus ancestros celebrando su sabiduría con magníficos festines y, por supuesto, ¡lanzando fuegos de artificio!|n', `description_ruru` = 'Каждый год друиды Лунной поляны устраивают празднество по случаю великой победы над древним злом. Во время Лунного фестиваля жители Азерота посещают своих предков и приобщаются к их мудрости, от души пируют и, разумеется... запускают фейерверки!' WHERE `id` = 17;
UPDATE `holidaydescriptions` SET `description_kokr` = '가을 축제는 드워프들이 시작했지만, 이제는 전 세계 모두가 함께 맛있는 음식과 흥겨운 일들을 즐기는 축제가 되었습니다.', `description_frfr` = 'Lancée par les nains, la fête des Brasseurs célèbre aujourd\'hui la bière et la fête partout dans le monde.', `description_dede` = 'Es wurde von den Zwergen ins Leben gerufen und feiert nun weltweit das Bier und die gute Stimmung.', `description_zhcn` = '由矮人创立的美酒节，现在已经成为世界性的享受美酒与快乐时光的欢庆节日。', `description_zhtw` = '最早由矮人所開始，啤酒節如今是個世界性的啤酒節慶與歡樂時光。', `description_eses` = 'La Fiesta de la cerveza, que fue inventada por los enanos, es una celebración mundial de cerveza y buenos ratos.', `description_esmx` = 'La Fiesta de la cerveza, que fue inventada por los enanos, es una celebración mundial de cerveza y buenos ratos.', `description_ruru` = 'Хмельной фестиваль – пора хорошего настроения. Первыми его стали проводить дворфы, но он приобрел популярность во всем мире.' WHERE `id` = 18;
UPDATE `holidaydescriptions` SET `description_kokr` = '고블린 마을인 무법항으로 항해해 온 드메자 선장이 해적단원을 모집합니다. 해적으로서 모험이 넘치는 생활을 꿈꿔왔다면 드메자 선장이나 주요 도시에 있는 부하를 만나 보세요!', `description_frfr` = 'Le capitaine DeMeza fait voile sur la ville gobeline de Baie-du-Butin. Elle recrute des amoureux de la terre dans les rangs de ses boucaniers.

Si vous vous sentez une âme de pirate, rendez visite au capitaine Demeza et à ses hommes de main dans les capitales !', `description_dede` = 'Kapitänin DeMeza segelt in die Goblinstadt Beutebucht und rekrutiert Landratten in ihre Ränge.

Wenn das Piratenleben was für Euch ist, dann sucht sie oder ihre Handlanger in einer der Hauptstädte auf!', `description_zhcn` = '德梅萨船长正在地精城市藏宝海湾征募海盗。

如果你对海盗生涯感兴趣的话，就去各大主城拜访她和她的随从们吧！', `description_zhtw` = '狄米撒船長來到了藏寶海灣的哥布林城鎮，並且招募新的海盜成員。

去拜訪她或她在主城的招募員，你也可以展開自己的海盜人生!', `description_eses` = 'La capitana Demeza navega hasta la ciudad goblin de Bahía Botín y recluta a los amantes del mar para que se unan a sus filas de bucaneros.

¡Ve a verla a ella o a sus secuaces a las capitales si lo tuyo es llevar una vida pirata!', `description_esmx` = 'La capitana Demeza navega hasta la ciudad goblin de Bahía Botín y recluta a los amantes del mar para que se unan a sus filas de bucaneros.

¡Ve a verla a ella o a sus secuaces a las capitales si lo tuyo es llevar una vida pirata!', `description_ruru` = 'Капитан де Меза захватила гоблинскую Пиратскую Бухту и приглашает всех сухопутных салаг присоединиться к ее команде. 

Если тебе по душе жизнь пирата – завербуйся на ее корабль! Пираты из ее шайки бродят во всех крупных городах Азерота.' WHERE `id` = 21;
UPDATE `holidaydescriptions` SET `description_kokr` = '알터랙 계곡에서 전투가 점점 치열해지고 있습니다. 종족을 위해 칼을 뽑아들고 알터랙 전투에 참여하는 이들에게는 크나큰 명예가 있을 것입니다.', `description_frfr` = 'La bataille pour la vallée d\'Alterac s\'intensifie. Un plus grand honneur est donné à ceux qui prêtent allégeance à leur seigneur et qui se battent à Alterac.', `description_dede` = 'Der Kampf um das Alteractal wird hitziger. Große Ehre wartet auf diejenigen, die für ihren Herren in die Schlacht um Alterac ziehen.', `description_zhcn` = '奥特兰克山谷的战斗愈发激烈。在奥特兰克山谷浴血奋战的勇士们必将载誉而归。', `description_zhtw` = '奧特蘭克山谷的戰鬥轉趨激烈。願意持劍投身奧特蘭克戰鬥的人將會獲得更大的榮譽。', `description_eses` = 'La batalla por el Valle de Alterac se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en Alterac se les reconoce gran honra.', `description_esmx` = 'La batalla por el Valle de Alterac se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en Alterac se les reconoce gran honra.', `description_ruru` = 'Не стихают бои в Альтеракской долине... Вечная слава отважным воинам, сражающимся на поле брани.' WHERE `id` = 22;
UPDATE `holidaydescriptions` SET `description_kokr` = '아라시 분지에서 전투가 점점 치열해지고 있습니다. 종족을 위해 칼을 뽑아들고 아라시 분지 전투에 참여하는 이들에게는 크나큰 명예가 있을 것입니다.', `description_frfr` = 'La bataille pour le bassin d\'Arathi s\'intensifie. Un plus grand honneur est donné à ceux qui prêtent allégeance à leur seigneur et qui se battent à Arathi.', `description_dede` = 'Der Kampf um das Arathibecken wird hitziger. Große Ehre wartet auf diejenigen, die für ihren Herren in die Schlacht um Arathi ziehen.', `description_zhcn` = '阿拉希盆地的战斗愈发激烈。在阿拉希盆地浴血奋战的勇士们必将载誉而归。', `description_zhtw` = '阿拉希盆地的戰鬥轉趨激烈。願意持劍投身阿拉希戰鬥的人將會獲得更大的榮譽。', `description_eses` = 'La batalla por la Cuenca de Arathi se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en Arathi se les reconoce gran honra.', `description_esmx` = 'La batalla por la Cuenca de Arathi se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en Arathi se les reconoce gran honra.', `description_ruru` = 'Не стихают бои в Низине Арати... Вечная слава отважным воинам, сражающимся на поле брани.' WHERE `id` = 23;
UPDATE `holidaydescriptions` SET `description_kokr` = '폭풍의 눈에서 전투가 점점 치열해지고 있습니다. 종족을 위해 칼을 뽑아들고 폭풍의 눈 전투에 참여하는 이들에게는 크나큰 명예가 있을 것입니다.', `description_frfr` = 'La bataille pour l\'Œil du cyclone s\'intensifie. Un plus grand honneur est donné à ceux qui prêtent allégeance à leur seigneur et qui se battent dans l\'Œil.', `description_dede` = 'Der Kampf um das Auge des Sturms wird hitziger. Große Ehre wartet auf diejenigen, die für ihren Herren in die Schlacht um das Auge ziehen.', `description_zhcn` = '风暴之眼的战斗愈发激烈。在风暴之眼浴血奋战的勇士们必将载誉而归。', `description_zhtw` = '暴風之眼的戰鬥轉趨激烈。願意持劍投身暴風之眼戰鬥的人將會獲得更大的榮譽。', `description_eses` = 'La batalla por el Ojo de la Tormenta se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en el Ojo de la Tormenta se les reconoce gran honra.', `description_esmx` = 'La batalla por el Ojo de la Tormenta se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en el Ojo de la Tormenta se les reconoce gran honra.', `description_ruru` = 'Не стихают бои на Оке Бури... Вечная слава отважным воинам, сражающимся на поле брани.' WHERE `id` = 24;
UPDATE `holidaydescriptions` SET `description_kokr` = '전쟁노래 협곡에서 전투가 점점 치열해지고 있습니다. 종족을 위해 칼을 뽑아들고 전쟁노래 협곡 전투에 참여하는 이들에게는 크나큰 명예가 있을 것입니다.', `description_frfr` = 'La bataille pour le goulet des Chanteguerres s\'intensifie. Un plus grand honneur est donné à ceux qui prêtent allégeance à leur seigneur et qui se battent dans le goulet.', `description_dede` = 'Der Kampf um die Kriegshymnenschlucht wird hitziger. Große Ehre wartet auf diejenigen, die für ihren Herren in die Schlacht um das die Schlucht ziehen.', `description_zhcn` = '战歌峡谷的战斗愈发激烈。在战歌峡谷浴血奋战的勇士们必将载誉而归。', `description_zhtw` = '戰歌峽谷的戰鬥轉趨激烈。願意持劍投身戰歌峽谷戰鬥的人將會獲得更大的榮譽。', `description_eses` = 'La batalla por la Garganta Grito de Guerra se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en la Garganta Grito de Guerra se les reconoce gran honra.', `description_esmx` = 'La batalla por la Garganta Grito de Guerra se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en la Garganta Grito de Guerra se les reconoce gran honra.', `description_ruru` = 'Не стихают бои в Ущелье Песни Войны... Вечная слава отважным воинам, сражающимся на поле брани.' WHERE `id` = 25;
UPDATE `holidaydescriptions` SET `description_kokr` = '이번에는 다크문 축제가 여기, 썬더 블러프 기슭에서 열립니다. 실라스 다크문과 그 유랑단을 만나 보세요. 속마음을 점쳐보기도 하고 아제로스 구석구석에서 모인 신기한 여러 가지를 즐기실 수도 있답니다... 이게 전부가 아니니 직접 가보세요!', `description_frfr` = 'La foire de Sombrelune est installée au pied des Pitons du Tonnerre.

Rendez visite à Silas Sombrelune et sa troupe, jouez à des jeux qui mettront à l\'épreuve votre esprit et vos nerfs, et découvrez des visions exotiques venues des quatre coins d\'Azeroth… et au-delà !', `description_dede` = 'Der Dunkelmond-Jahrmarkt ist hier, diesmal am Fuße von Donnerfels.

Trefft Silas Dunkelmond und seine Truppe, spielt Spiele, die Kopf und Nerven auf die Probe stellen und bewundert exotische Anblicke aus allen Himmelsrichtungen Azeroths... und darüber hinaus!', `description_zhcn` = '这一次，暗月马戏团来到了雷霆崖的脚下。

去拜访希拉斯·暗月和他的马戏团，玩一玩考验头脑和胆量的游戏，看一看来自艾泽拉斯各地的奇特珍品……还有更多的乐趣在等着你！', `description_zhtw` = '暗月馬戲團來了，就在雷霆崖的山腳下。

快來看看希拉斯·暗月和他的戲團，參與一些考驗智慧與膽量的遊戲，目睹來自艾澤拉斯各地的驚奇景象…以及更多新奇的事物在此等著你!', `description_eses` = 'La Feria de la Luna Negra está aquí y ahora, al pie de la Cima del Trueno.

Conoce a Silas Lunanegra y a su compañía, diviértete con juegos que ponen a prueba tu mente y tu nervio, y contempla vistas exóticas de todos los rincones de Azeroth... ¡y más allá!', `description_esmx` = 'La Feria de la Luna Negra está aquí y ahora, al pie de la Cima del Trueno.

Conoce a Silas Lunanegra y a su compañía, diviértete con juegos que ponen a prueba tu mente y tu nervio, y contempla vistas exóticas de todos los rincones de Azeroth... ¡y más allá!', `description_ruru` = 'К подножию Громового Утеса приехала Ярмарка Новолуния!

Познакомься с Сайласом Новолунием и его труппой, испытай свою смелость и ловкость и полюбуйся роскошными видами со всего Азерота и за его пределами!' WHERE `id` = 26;
UPDATE `holidaydescriptions` SET `description_kokr` = '이번에는 다크문 축제가 여기, 샤트라스 외곽에서 열립니다. 실라스 다크문과 그 유랑단을 만나 보세요. 속마음을 점쳐보기도 하고 아제로스 구석구석에서 모인 신기한 여러 가지를 즐기실 수도 있답니다... 이게 전부가 아니니 직접 가보세요!', `description_frfr` = 'La foire de Sombrelune est installée à l\'extérieur de Shattrath.

Rendez visite à Silas Sombrelune et sa troupe, jouez à des jeux qui mettront à l\'épreuve votre esprit et vos nerfs, et découvrez des visions exotiques venues des quatre coins d\'Azeroth… et au-delà !', `description_dede` = 'Der Dunkelmond-Jahrmarkt ist hier, diesmal außerhalb von Shattrath.

Trefft Silas Dunkelmond und seine Truppe, spielt Spiele, die Kopf und Nerven auf die Probe stellen und bewundert exotische Anblicke aus allen Himmelsrichtungen Azeroths... und darüber hinaus!', `description_zhcn` = '这一次，暗月马戏团来到了沙塔斯城外。

去拜访希拉斯·暗月和他的马戏团，玩一玩考验头脑和胆量的游戏，看一看来自艾泽拉斯各地的奇特珍品……还有更多的乐趣在等着你！', `description_zhtw` = '暗月馬戲團來了，就在撒塔斯城外。

快來看看希拉斯·暗月和他的戲團，參與一些考驗智慧與膽量的遊戲，目睹來自艾澤拉斯各地的驚奇景象…以及更多新奇的事物在此等著你!', `description_eses` = 'La Feria de la Luna Negra ya está aquí, a las afueras de la Ciudad de Shattrath.

Conoce a Silas Lunanegra y a su compañía, diviértete con juegos que ponen a prueba tu mente y tu nervio, y contempla vistas exóticas de todos los rincones de Azeroth... ¡y más allá!', `description_esmx` = 'La Feria de la Luna Negra ya está aquí, a las afueras de la Ciudad de Shattrath.

Conoce a Silas Lunanegra y a su compañía, diviértete con juegos que ponen a prueba tu mente y tu nervio, y contempla vistas exóticas de todos los rincones de Azeroth... ¡y más allá!', `description_ruru` = 'В Шаттрат приехала Ярмарка Новолуния!

Познакомься с Сайласом Новолунием и его труппой, испытай свою смелость и ловкость и полюбуйся роскошными видами со всего Азерота и за его пределами!' WHERE `id` = 27;
UPDATE `holidaydescriptions` SET `description_kokr` = '고대의 해안에서 벌어지고 있는 전투의 열기가 점점 뜨거워지고 있습니다. 종족을 위해 칼을 뽑아들고 고대의 해안 전투에 참여하는 자에게는 커다란 명예가 주어질 것입니다.', `description_frfr` = 'La bataille pour le rivage des Anciens s\'intensifie. Un plus grand honneur est donné à ceux qui prêtent allégeance à leur seigneur et qui se battent sur le rivage des Anciens.', `description_dede` = 'Der Kampf um den Strand der Uralten wird hitziger. Große Ehre wartet auf diejenigen, die für ihren Herren in die Schlacht um den Strand ziehen.', `description_zhcn` = '远古海滩的战斗愈发激烈。在远古海滩浴血奋战的勇士们必将载誉而归。', `description_zhtw` = '遠祖灘頭的戰鬥轉趨激烈。願意持劍投身遠祖灘頭戰鬥的人將會獲得更大的榮譽。', `description_eses` = 'La batalla por la Playa de los Ancestros se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en la Playa de los Ancestros se les reconoce gran honra.', `description_esmx` = 'La batalla por la Playa de los Ancestros se hace cada vez más intensa. A aquellos que ofrecen la espada en nombre de su Señor y batallan en la Playa de los Ancestros se les reconoce gran honra.', `description_ruru` = 'Не стихают бои на Береге Древних. Вечная слава отважным воинам, сражающимся на поле брани.' WHERE `id` = 41;
UPDATE `holidaydescriptions` SET `description_kokr` = '리치 왕의 분노가 출시됩니다.

얼라이언스 배는 스톰윈드와 메네실 항구에서,

호드 비행선은 오그리마와 언더시티 앞에서 출발합니다.

노스렌드에서 다시 만나요!', `description_frfr` = 'Le départ pour le courroux du roi-liche se fera le 13 novembre.

Des vaisseaux de l\'Alliance prendront la mer depuis les ports de Ménéthil et Hurlevent.

Des zeppelins de la Horde largueront leurs amarres à l\'extérieur d\'Orgrimmar et de Fossoyeuse.

À bientôt en Norfendre...', `description_dede` = 'Wrath of the Lich King erscheint am 13. November.

Schiffe der Allianz legen von den Häfen von Sturmwind und Menethil ab.

Zeppeline der Horde starten außerhalb von Orgrimmar und Unterstadt.

Wir sehen uns in Nordend...', `description_zhcn` = '巫妖王之怒于11月13日正式上线。

诺森德再会……', `description_zhtw` = '巫妖王之怒將於11月13日發行。

聯盟船隻將從暴風城與米奈希爾港出發。

部落飛艇將從奧格瑪和幽暗城外出發。

我們北裂境見……', `description_eses` = 'El lanzamiento de Wrath of the Lich King tendrá lugar el 13 de noviembre.

Los barcos de la Alianza salen de Ventormenta y del Puerto de Menethil.

Los zepelines de la Horda parten desde las afueras de Orgrimmar y Entrañas.

Nos vemos en Rasganorte.', `description_esmx` = 'El lanzamiento de Wrath of the Lich King tendrá lugar el 13 de noviembre.

Los barcos de la Alianza salen de Ventormenta y del Puerto de Menethil.

Los zepelines de la Horda parten desde las afueras de Orgrimmar y Entrañas.

Nos vemos en Rasganorte.', `description_ruru` = 'Запуск Wrath of the Lich King состоится 13 ноября.

Корабли Альянса отправляются из порта Штормграда и Гавани Менетилов.

Дирижабли Орды стартуют неподалеку от Оргриммара и Подгорода.

Увидимся в Нордсколе…' WHERE `id` = 61;
UPDATE `holidaydescriptions` SET `description_kokr` = '망자의 날에는 다같이 무덤가에 모여 떠나간 이들의 영혼을 기리며 축제를 엽니다.

대도시의 공동묘지에 가시면 축하객들이 요리하고 춤추며, 특별 복장을 입고 즐기는 모습을 보실 수 있습니다.', `description_frfr` = 'À l\'occasion du Jour des morts, les gens se rassemblent dans les cimetières pour célébrer et chérir la mémoire de leurs proches disparus.

Les festivités se déroulent dans les cimetières des grandes villes, où les participants se réunissent pour cuisiner, danser, ou encore pour se déguiser.', `description_dede` = 'Am Tag der Toten trifft man sich auf den Friedhöfen, um das Andenken derjenigen zu ehren, die man verloren hat, und um mit ihren Geistern zu feiern.

Die Feierlichkeiten finden auf den Friedhöfen aller großen Städte statt und beinhalten festliche Speisen, Tanz, Kostüme und vieles mehr.', `description_zhcn` = '在悼念日，人们会聚集在墓地来告慰逝者的亡魂。

届时任何主城的公墓都会举行仪式，在那里有悼念日食品、舞蹈、化装聚会和其他活动。', `description_zhtw` = '在亡者節的時候，人們聚集在墓園中慶祝，和親人的鬼魂一起同樂。

你可以在各大主城的墓園發現慶典活動，你可以在那邊烹飪、跳舞、扮裝還有許許多多的活動。', `description_eses` = 'Durante la Festividad de los Muertos, la gente se reúne en los cementerios para rendir homenaje a los espíritus de aquellos que han partido.

Las celebraciones pueden encontrarse en los cementerios de cualquier ciudad importante, donde sus participantes cocinan, bailan, lucen sus atuendos y más.', `description_esmx` = 'Durante la Festividad de los Muertos, la gente se reúne en los cementerios para rendir homenaje a los espíritus de aquellos que han partido.

Las celebraciones pueden encontrarse en los cementerios de cualquier ciudad importante, donde sus participantes cocinan, bailan, lucen sus atuendos y más.', `description_ruru` = 'В День мертвых люди собираются на кладбищах, чтобы почтить память дорогих им умерших.

Празднование проходит на кладбищах всех крупных городов. Во время праздника принято готовить угощения, танцевать, облачаться в костюмы и веселиться.' WHERE `id` = 81;
UPDATE `holidaydescriptions` SET `description_kokr` = '순례자의 감사절은 누군가 겪었던 좋은 일을 떠올리고 주변에 있는 모두와 함께 나누는 시간입니다.', `description_frfr` = 'Les Bienfaits du pèlerin est un moment où l\'on se rappelle que la chance nous a souri, et où l\'on partage son repas avec tous ceux qui nous entourent.', `description_dede` = 'Das Pilgerfreudenfest ist eine Zeit, dem eigenen Glück zu gedenken und es Anderen zu schenken.', `description_zhcn` = '感恩节是一场感谢好运，并将自己的幸福和周围的人们共同分享的节日。', `description_zhtw` = '旅人豐年祭是與他人分享好運的節日。', `description_eses` = 'Generosidad del Peregrino es una ocasión para reflexionar sobre la buena suerte de uno mismo y para compartir con aquellos que te rodean.', `description_esmx` = 'Generosidad del Peregrino es una ocasión para reflexionar sobre la buena suerte de uno mismo y para compartir con aquellos que te rodean.', `description_ruru` = 'Пиршество странников – время поблагодарить судьбу за щедрость и разделить ее дары со всеми вокруг.' WHERE `id` = 101;
UPDATE `holidaydescriptions` SET `description_kokr` = '정복의 섬에서 전투가 점점 치열해지고 있습니다. 종족을 위해 칼을 뽑아들고 정복의 섬 전투에 참여하는 이들에게는 크나큰 명예가 있을 것입니다.', `description_frfr` = 'La bataille pour l\'île des Conquérants s\'intensifie. Un plus grand honneur est donné à ceux qui prêtent allégeance à leur seigneur et qui se battent sur l\'île.', `description_dede` = 'Der Kampf um die Insel der Eroberung wird hitziger. Große Ehre wartet auf diejenigen, die für ihren Herren in die Schlacht um die Insel ziehen.', `description_zhcn` = '征服之岛的战斗愈发激烈。在征服之岛浴血奋战的勇士们必将载誉而归。', `description_zhtw` = '征服之島的戰鬥轉趨激烈。願意持劍投身島上戰鬥的人將會獲得更大的榮譽。', `description_eses` = 'La batalla por la Isla de la Conquista se está volviendo más intensa. Aquellos que entreguen su espada a su señor y luchen en la isla obtendrán grandes honores.', `description_esmx` = 'La batalla por la Isla de la Conquista se está volviendo más intensa. Aquellos que entreguen su espada a su señor y luchen en la isla obtendrán grandes honores.', `description_ruru` = 'Не стихают бои на Острове Завоеваний… Великая слава ждет тех, чей меч не ведает устали, кто не жалеет сил ради победы.' WHERE `id` = 121;
UPDATE `holidaydescriptions` SET `description_kokr` = '시험용', `description_frfr` = 'Test test', `description_dede` = 'Test test', `description_zhcn` = 'Test test', `description_zhtw` = 'Test test', `description_eses` = 'Test test', `description_esmx` = 'Test test', `description_ruru` = 'Test test' WHERE `id` = 141;
UPDATE `holidaydescriptions` SET `description_kokr` = '노스렌드에서는 며칠에 한 번씩 칼루아크 낚시 대축제가 열립니다. 가장 먼저 흑기흉상어를 잡아 칼루아크에게 인정 받고, 놀라운 상품도 얻으세요!', `description_frfr` = 'Les Kalu\'ak organisent un tournoi de pêche tous les quelques jours en Norfendre. Attrapez en premier un requin pointe-noire et gagnez le respect des Kalu\'ak, ainsi qu\'une incroyable récompense !', `description_dede` = 'Die Kalu\'ak halten alle paar Tage einen Angelwettstreit in Nordend ab. Seid der erste, der einen Schwarzspitzenhai aus dem Wasser zieht und erringt den Respekt der Kalu\'ak sowie einen großartigen Preis!', `description_zhcn` = '卡鲁亚克人每隔几天就会在诺森德举办一次钓鱼大赛。第一位钓到黑鳍鲨的人将会赢得卡鲁亚克人的敬意，并且获得一份惊喜！', `description_zhtw` = '卡魯耶克每隔幾天就會在北裂境舉行釣魚大賽。首先釣起黑尖鯊魚的參賽者將會贏得卡魯耶克的敬重以及大獎!', `description_eses` = 'Los Kalu\'ak hacen una competición de pesca cada varios días en Rasganorte. Sé el primero en pescar un tiburón macuira y gánate el respeto de los Kalu\'ak. ¡Y un premio alucinante!', `description_esmx` = 'Los Kalu\'ak hacen una competición de pesca cada varios días en Rasganorte. Sé el primero en pescar un tiburón macuira y gánate el respeto de los Kalu\'ak. ¡Y un premio alucinante!', `description_ruru` = 'Калуакское рыбоборье проводится раз в несколько дней в Нордсколе. Поймайте черную акулу раньше всех, и вы заслужите уважение Калу\'ак и заманчивый приз!' WHERE `id` = 161;
